import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        // 1. Pre-sizing with known initial capacity
        ArrayList<String> list = new ArrayList<>(5);
        list.add("A");
        list.add("B");
        list.add("D");
        list.add("E");
        System.out.println("Initial List: " + list);

        // 2. Positional Insertion (Shifts 'D' and 'E' one slot to the right)
        list.add(2, "C"); 
        System.out.println("After inserting 'C' at index 2: " + list);

        // 3. Fast O(1) Random Access
        String itemAt2 = list.get(2);
        System.out.println("Element at index 2: " + itemAt2);

        // 4. Positional Deletion (Shifts 'D' and 'E' one slot to the left)
        String removed = list.remove(2);
        System.out.println("Removed item: " + removed);
        System.out.println("After removing index 2: " + list);

        // 5. Trimming unused buffer capacity to current size
        list.trimToSize();
        System.out.println("Trimmed list size: " + list.size());
    }
}

