public class Main {
    public static void main(String[] args) {
        int capacity = 10;
        int step = 0;

        while (capacity <= 100) {
            step++;
            capacity = capacity + (capacity >> 1);
            System.out.println("Step " + step + ": Capacity = " + capacity);
        }

        System.out.println("Total Expansions: " + step);
    }
}

