        List<Integer> listDefault = new ArrayList<>();
        for (int i = 1; i <= 50000; i++) {
            listDefault.add(i);
        }

        List<Integer> listPresized = new ArrayList<>(50000);
        for (int i = 1; i <= 50000; i++) {
            listPresized.add(i);
        }

        System.out.println("Default List Size: " + listDefault.size());
        System.out.println("Presized List Size: " + listPresized.size());
        System.out.println("Lists Match: " + listDefault.equals(listPresized));
    }
}

