public class Main {
    public static int calculateShifts(int currentSize, int insertIndex) {
        if (insertIndex < 0 || insertIndex > currentSize) {
            throw new IndexOutOfBoundsException();
        }
        return currentSize - insertIndex;
    }

    public static void main(String[] args) {
        int size = 10;
        System.out.println("Head Insert Shifts: " + calculateShifts(size, 0));
        System.out.println("Middle Insert Shifts: " + calculateShifts(size, 5));
        System.out.println("Tail Insert Shifts: " + calculateShifts(size, 10));
    }
}

