import java.util.ArrayList;

public class Main {
    public static void main(String[] args) {
        ArrayList<String> list = new ArrayList<>(1000);
        for (int i = 0; i < 1000; i++) {
            list.add("RECORD-" + i);
        }

        System.out.println("Peak Size: " + list.size());

        // Retain only top 5
        list.subList(5, list.size()).clear();
        list.trimToSize();

        System.out.println("Retained Size: " + list.size());
        System.out.println("Final Records: " + list);
    }
}

